function form(title,fields,cb){const d=document.createElement('div');d.className='modal';d.innerHTML=`<form><h3 style="margin:0 0 6px">${title}</h3>${fields.map(f=>`<label>${f.l}${f.t==='select'?`<select name="${f.k}">${f.o.map(o=>`<option value="${esc(o[0])}">${esc(o[1])}</option>`).join('')}</select>`:`<input name="${f.k}" type="${f.t||'text'}" placeholder="${esc(f.ph||'')}">`}</label>`).join('')}<div class="row" style="margin-top:12px;justify-content:flex-end"><button type="button" class="btn g" data-x>Cancel</button><button class="btn">Save</button></div></form>`;
document.body.appendChild(d);d.addEventListener('click',e=>{if(e.target===d||e.target.dataset.x!==undefined)d.remove()});
d.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));cb(v);d.remove();save();render();toast('Saved ✓')})}
const csv=s=>s.split(',').map(x=>x.trim().toLowerCase()).filter(Boolean),opts=a=>a.map(x=>[x,x]);
const A={
v:id=>{view=id;q='';render()},
refreshSuggest:()=>{try{const latest=JSON.parse(localStorage.getItem('sgp'));if(latest&&latest.m){S=latest;S.lead=S.lead||[];S.notices=Array.isArray(S.notices)?S.notices:[]}}catch(e){}render();toast('AI suggestions refreshed from the latest team data')},
openProj:id=>{projectId=+id;view='pdetail';q='';render()},
autoProject:id=>{if(ROLE!=='leader')return toast('Only team leaders can auto-assign project tasks.');autoAssign(+id)},
generateProject:id=>{if(ROLE!=='leader')return toast('Only team leaders can create and assign project tasks.');generateProjectTasks(+id)},
theme:()=>{const r=document.documentElement,dk=r.dataset.theme==='dark';r.dataset.theme=dk?'light':'dark';try{localStorage.setItem('sgt',r.dataset.theme)}catch(e){}},
chat:()=>{$('#chat').classList.toggle('on');if(!$('#msgs').children.length)say('b','Hello! I’m your local SmartGroup assistant. I can explain team pros and cons, member workload, skills, project risks and task assignments. Ask in your own words or choose a suggestion below.')},
mv:(id,t)=>{const o=['todo','doing','done'],x=S.t.find(a=>a.id==id);if(!canMove(x))return;x.st=o[Math.max(0,Math.min(2,o.indexOf(x.st)+ +t.dataset.d))];save();render()},
delT:id=>{S.t=S.t.filter(t=>t.id!=id);save();render()},delP:id=>{S.p=S.p.filter(t=>t.id!=id);save();render()},
delM:id=>{S.m=S.m.filter(t=>t.id!=id);S.t.forEach(t=>{if(t.as==id)t.as=0});save();render()},
editM:id=>{const m=mem(+id),self=ROLE==='member'&&myM()?.id==id;if(!m||!(ROLE==='leader'||self))return toast('You can only edit your own profile.');form(self?'Edit your profile':'Edit member profile',[F('name','Full name'),F('skills','Skills (comma separated)','text',0,'java, react'),F('exp','Skill level','select',opts(['Beginner','Intermediate','Advanced'])),F('av','Availability','select',opts(['Available','Busy']))],v=>{m.name=v.name.trim()||m.name;m.skills=csv(v.skills);m.exp=v.exp;m.av=v.av;if(self&&ACC){ACC.name=m.name;chip();const update=async()=>{const a=await accGet(ACC.id);if(a){a.name=m.name;a.skills=m.skills;a.exp=m.exp;await accSet(ACC.id,a)}};update().catch(()=>toast('Profile saved, but account details could not be synced.'))}})},
mine:()=>{mine=!mine;render()},
claim:id=>{S.m.forEach(m=>{if(m.uid===ME.id)delete m.uid});S.m.find(m=>m.id==id).uid=ME.id;save();render();toast('Linked to your account')},
auto:()=>{if(!S.m.length)return toast('Add a team member before auto-assigning');const rank={High:3,Medium:2,Low:1},pending=S.t.filter(t=>open(t)&&!t.as).sort((a,b)=>(rank[b.pr]||0)-(rank[a.pr]||0)||String(a.dl||'9999').localeCompare(String(b.dl||'9999')));let n=0;pending.forEach(t=>{const pick=best(t);if(pick){assignTask(t,pick.m.id);n++}});if(n)save();render();toast(n?`Auto-assigned ${n} task(s) by skill fit, availability and workload`:'No unassigned open tasks to assign')},
addM:()=>form('Add Member',[F('name','Full name'),F('role','Role'),F('skills','Skills (comma separated)','text',0,'java, react'),F('exp','Experience','select',opts(['Beginner','Intermediate','Advanced'])),F('av','Availability','select',opts(['Available','Busy']))],v=>S.m.push({id:S.n++,name:v.name||'New member',role:v.role,skills:csv(v.skills),exp:v.exp,av:v.av})),
addP:()=>form('New Project',[F('name','Project name'),F('desc','Description'),F('stack','Tech stack (comma separated)'),F('start','Start date','date'),F('deadline','Deadline','date'),F('status','Status','select',opts(['Planning','In Progress','Completed'])),F('progress','Progress %','number')],v=>S.p.push({id:S.n++,name:v.name||'Untitled',desc:v.desc,stack:csv(v.stack),start:v.start||day(0),deadline:v.deadline||day(30),status:v.status,progress:Math.min(100,+v.progress||0)})),
addT:()=>form('Create Task',[F('title','Task name'),F('as','Assign to','select',[['0','Unassigned (AI picks)'],...S.m.map(m=>[m.id,m.name])]),F('pr','Priority','select',opts(['High','Medium','Low'])),F('dl','Deadline','date'),F('pj','Project','select',S.p.map(p=>[p.id,p.name])),F('sk','Required skills (comma separated)')],v=>{const t={id:S.n++,title:v.title||'Untitled',as:0,pr:v.pr,st:'todo',dl:v.dl,pj:+v.pj,sk:csv(v.sk)};S.t.push(t);assignTask(t,+v.as||best(t)?.m.id)})};
function autoAssign(project){if(!S.m.length)return toast('Add a team member before auto-assigning');if(!S.m.some(m=>m.av==='Available'))return toast('No team members are marked Available. Update a member’s availability and try again.');const rank={High:3,Medium:2,Low:1},pending=S.t.filter(t=>open(t)&&!t.as&&(project===undefined||t.pj==project)).sort((a,b)=>(rank[b.pr]||0)-(rank[a.pr]||0)||String(a.dl||'9999').localeCompare(String(b.dl||'9999')));let n=0;pending.forEach(t=>{const pick=bestAvailable(t);if(pick){assignTask(t,pick.m.id);n++}});if(n)save();render();toast(n?'Assigned '+n+' task(s) to available members by skill match, level and workload':project===undefined?'No unassigned open tasks have an available skill match':S.t.some(t=>t.pj==project)?'No unassigned tasks have a matching available member':'Add project tasks first, then auto-assign them.')}
function generateProjectTasks(id){const p=pj(id);if(!p)return;if(!S.m.some(m=>m.av==='Available'))return toast('No team members are marked Available. Update a member’s availability and try again.');if(S.t.some(t=>t.pj==id))return toast('This project already has tasks. Use Auto-assign for its unassigned work.');const skills=[...new Set((p.stack||[]).filter(Boolean))],titles={java:`Build the ${p.name} backend`,react:`Build the ${p.name} interface`,html:`Build the ${p.name} interface`,css:`Style the ${p.name} interface`,js:`Add interactions to the ${p.name} interface`,sql:`Design the ${p.name} data layer`,python:`Build data processing for ${p.name}`,ml:`Build analytics for ${p.name}`,testing:`Test ${p.name} workflows`,selenium:`Automate tests for ${p.name}`,go:`Build the ${p.name} service`},specs=[];skills.slice(0,3).forEach(s=>specs.push({title:titles[s]||`Implement ${p.name} work using ${s}`,sk:[s]}));if(skills.length&&!specs.some(x=>x.sk.includes('testing')))specs.push({title:`Test and review ${p.name}`,sk:S.m.some(m=>m.skills.includes('testing'))?['testing']:[]});if(!specs.length)specs.push({title:`Define ${p.name} requirements`,sk:[]},{title:`Build the first ${p.name} deliverable`,sk:[]},{title:`Test and review ${p.name}`,sk:[]});let assigned=0;specs.forEach((x,i)=>{const t={id:S.n++,title:x.title,as:0,pr:i===0?'High':i===specs.length-1?'Low':'Medium',st:'todo',dl:p.deadline||day(7),pj:p.id,sk:x.sk};S.t.push(t);const pick=bestAvailable(t);if(pick){assignTask(t,pick.m.id);assigned++}});save();render();toast(`Created ${specs.length} starter task(s); assigned ${assigned}${specs.length-assigned?`, ${specs.length-assigned} need a matching available skill`:''}.`)}
const LEAD=['addM','addP','addT','delT','delP','delM','auto','autoProject','generateProject','claim','promote'],RO=[...LEAD,'editM','mv'];
document.addEventListener('click',e=>{const t=e.target.closest('[data-a]');if(t&&((ROLE==='viewer'&&RO.includes(t.dataset.a))||(ROLE==='member'&&LEAD.includes(t.dataset.a))))return;if(t&&A[t.dataset.a])A[t.dataset.a](t.dataset.id,t)});
window.addEventListener('storage',e=>{if(e.key==='sgp'&&e.newValue){try{const latest=JSON.parse(e.newValue);if(latest&&latest.m){S=latest;S.lead=S.lead||[];S.notices=Array.isArray(S.notices)?S.notices:[];render()}}catch(x){}}});
document.addEventListener('keydown',e=>{const c=e.target.closest('.project-card[role="button"]');if(c&&e.target===c&&(e.key==='Enter'||e.key===' ')){e.preventDefault();A.openProj(c.dataset.id)}});
document.addEventListener('input',e=>{if(e.target.id==='q'){q=e.target.value;const p=e.target.selectionStart;render();const n=$('#q');n.focus();n.setSelectionRange(p,p)}});
let drag;document.addEventListener('dragstart',e=>{drag=e.target.dataset?.tid});
document.addEventListener('dragover',e=>{const c=e.target.closest('[data-col]');if(c){e.preventDefault();c.classList.add('over')}});
document.addEventListener('dragleave',e=>{e.target.closest?.('[data-col]')?.classList.remove('over')});
document.addEventListener('drop',e=>{const c=e.target.closest('[data-col]');const x=S.t.find(t=>t.id==drag);if(c&&x&&canMove(x)){e.preventDefault();x.st=c.dataset.col;save();render()}});
// assistant (rule-based, runs locally)
function say(w,t){const m=document.createElement('div');m.className='m '+w;m.textContent=t;$('#msgs').appendChild(m);$('#msgs').scrollTop=9e9}
let chatMemberId=null;
function reply(query){const t=query.trim().toLowerCase(),rk=risks(),openTasks=S.t.filter(open),words=new Set(t.match(/[a-z0-9]+/g)||[]),mentioned=S.m.find(m=>t.includes(m.name.toLowerCase())||words.has(m.name.split(' ')[0].toLowerCase())),member=mentioned||S.m.find(m=>m.id===chatMemberId);
if(mentioned)chatMemberId=mentioned.id;
if(/^(hi|hello|hey|good morning|good afternoon)\b/.test(t))return `Hello! I can help you understand ${S.m.length} team member(s), ${S.p.length} project(s), and ${openTasks.length} open task(s). Ask about workload, a member's strengths, project risks, or task assignments.`;
if(member&&/(pros|cons|strength|weakness|performance|doing|workload|tasks for|tell me about|who is|what does|assigned)/.test(t)){const r=reviewMember(member,teamReview().needed),assigned=S.t.filter(x=>open(x)&&x.as==member.id);return `${member.name} is a ${member.exp.toLowerCase()}-level ${member.role}, marked ${member.av.toLowerCase()}, with a workload of ${load(member)} points. ${assigned.length?`They have ${assigned.length} open task(s): ${assigned.map(x=>x.title).join(', ')}.`:'They have no open tasks assigned.'}\n\nPros\n• ${r.pros.join('\n• ')}\n\nCons to watch\n• ${r.cons.join('\n• ')}`}
if(/\b(pros|advantages|strengths)\b/.test(t)){const r=teamReview();return `Here are the team's current strengths:\n• ${r.pros.join('\n• ')}\n\nThese are based on the skills, availability and task records entered in this workspace.`}
if(/\b(cons|weaknesses|weakness|downsides|watch.?outs)\b/.test(t)){const r=teamReview();return `The main concerns I can see are:\n• ${r.cons.join('\n• ')}\n\nAddressing unassigned work and skill gaps should improve the team's readiness.`}
if(/\b(improve|improvement|recommend|recommendation|better|advice)\b/.test(t)){const r=teamReview(),tips=[];if(r.gaps.length)tips.push(`Add or develop coverage for ${r.gaps.join(', ')}.`);if(r.unassigned)tips.push(`Assign the ${r.unassigned} unassigned task(s); use Auto-assign open tasks to get skill- and workload-aware suggestions.`);if(S.m.some(m=>load(m)>=6))tips.push('Review high-workload members and redistribute some open tasks.');if(S.t.some(late))tips.push('Prioritize overdue tasks before taking on more work.');if(!tips.length)tips.push('The current records show no urgent team issue. Keep skills and availability up to date and review project deadlines regularly.');return `Based on the current workspace, I suggest:\n• ${tips.join('\n• ')}`}
if(/\b(overdue|late|past due)\b/.test(t)){const l=S.t.filter(late);return l.length?`There ${l.length===1?'is':'are'} ${l.length} overdue task(s): ${l.map(x=>`“${x.title}” (due ${x.dl||'date not set'})`).join(', ')}.`:'There are no overdue open tasks right now.'}
if(/\b(risk|risks|danger|problem|at risk)\b/.test(t))return rk.length?`I found ${rk.length} current warning(s):\n• ${rk.map(r=>r[1]).join('\n• ')}`:'I do not see any current risks in the recorded tasks and projects.';
if(/\b(work ?load|busy|capacity|available|availability|overload)\b/.test(t)){const rows=S.m.map(m=>`${m.name}: ${load(m)} workload point(s), ${m.av.toLowerCase()}${m.av==='Available'&&load(m)<6?' with room for work':''}`);return rows.length?`Here is the current team capacity:\n• ${rows.join('\n• ')}`:'There are no team members yet. Add members to get workload guidance.'}
if(/\b(skill|skills|expertise|coverage|skill gap)\b/.test(t)){const r=teamReview(),all=[...new Set(S.m.flatMap(m=>m.skills))];return `The team has ${all.length?all.join(', '):'no recorded skills yet'}. ${r.gaps.length?`The current open tasks need skills not covered by the roster: ${r.gaps.join(', ')}.`:'All skills listed on open tasks are represented in the roster.'}`}
if(/\b(assign|assignment|who should|best person|auto.?assign)\b/.test(t)){const pending=openTasks.filter(x=>!x.as);if(!pending.length)return 'All open tasks already have an owner. Auto-assign only fills unassigned open tasks, so it will leave existing assignments unchanged.';if(!S.m.length)return 'There are unassigned tasks, but no team members to recommend. Add a member with skills first.';return `I found ${pending.length} unassigned open task(s). Suggested matches:\n• ${pending.map(x=>{const b=best(x);return `${x.title} (${x.pr} priority) → ${b.m.name}${x.sk.length?` · ${x.sk.filter(s=>b.m.skills.includes(s)).length} skill match(es)`:''}`}).join('\n• ')}\n\nUse Auto-assign open tasks to apply these suggestions. It considers priority, deadline, skill fit, availability, experience and workload.`}
if(/\b(task|tasks|todo|to-do|work items?)\b/.test(t)){if(/\b(done|complete|completed|finished)\b/.test(t)){const done=S.t.filter(x=>!open(x));return done.length?`The team has completed ${done.length} task(s): ${done.map(x=>x.title).join(', ')}.`:'No tasks are marked complete yet.'}return `There are ${openTasks.length} open task(s): ${openTasks.map(x=>`${x.title} — ${x.st==='doing'?'in progress':'to do'}, ${x.pr} priority, ${mem(x.as)?.name||'unassigned'}`).join('; ')||'none'}.`}
if(/\b(project|projects|progress|schedule|deadline|finish|eta|estimate)\b/.test(t)){const reports=analyze();if(!reports.length)return 'There are no projects to analyze yet. Add a project and tasks to get progress and schedule insights.';return `Project snapshot:\n• ${reports.map(a=>`${a.p.name}: ${a.status}, ${a.bp}% estimated progress${a.fin?'':`, estimated finish ${a.eta}`}`).join('\n• ')}\n\nEstimates use task priorities and recorded dates, so keep those details current.`}
if(/\b(summary|status|overview|team|members|roster)\b/.test(t))return `Current snapshot: ${S.m.length} member(s), ${S.p.length} project(s), ${S.t.length} task(s), ${openTasks.length} open and ${S.t.length-openTasks.length} completed. There are ${S.t.filter(late).length} overdue task(s) and ${openTasks.filter(x=>!x.as).length} unassigned open task(s).`;
if(/\b(help|how do i|how can i|what can|features|use the app)\b/.test(t))return 'To get started, create a project and add tasks with required skills and deadlines. Add team members with their skills and skill levels. The Team Analyzer shows strengths, concerns, skill gaps and project risks. On the Task Board, a leader can auto-assign unowned tasks using skill fit, availability, experience and workload. Members can update the status of their own tasks.';
return `I can answer questions using this workspace's team and project data. Try asking about a member by name, team pros and cons, workload, skills, overdue tasks, project progress, risks, or who should take an unassigned task. I work locally and do not have live internet or general world knowledge.`}
['Team pros and cons','Who has capacity?','Project risks','Who should take tasks?'].forEach(c=>{const b=document.createElement('button');b.className='btn g s';b.textContent=c;b.onclick=()=>{say('u',c);say('b',reply(c))};$('#chips').appendChild(b)});
$('#cf').addEventListener('submit',e=>{e.preventDefault();const v=$('#ci').value.trim();if(!v)return;$('#ci').value='';say('u',v);say('b',reply(v))});
const hx=b=>[...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join(''),te=new TextEncoder(),rnd=()=>hx(crypto.getRandomValues(new Uint8Array(16)));
async function pw(p,salt){const k=await crypto.subtle.importKey('raw',te.encode(p),'PBKDF2',false,['deriveBits']);return hx(await crypto.subtle.deriveBits({name:'PBKDF2',hash:'SHA-256',salt:te.encode(salt),iterations:100000},k,256))}
const aid=async e=>hx(await crypto.subtle.digest('SHA-256',te.encode(e))).slice(0,24);
const LS=k=>{try{return JSON.parse(localStorage.getItem(k))}catch(e){return null}};
async function accGet(id){if(DB){const x=await DB.doc('accounts/'+id).get();return x.exists?x.data():null}return LS('sga:'+id)}
async function accSet(id,o){if(DB)return DB.doc('accounts/'+id).set(o);localStorage.setItem('sga:'+id,JSON.stringify(o))}
async function cfgGet(){if(DB){const x=await DB.doc('team/config').get();return x.exists?x.data():null}return LS('sgc')}
async function cfgSet(o){if(DB)return DB.doc('team/config').set(o);localStorage.setItem('sgc',JSON.stringify(o))}
function chip(){const e=$('#me'),rl={leader:'👑 Team Leader',member:'🙋 Team Member',viewer:'👁 Read-only'}[ROLE];
e.innerHTML=ACC?`<div class="row" style="justify-content:flex-start"><div class="av">${esc(ini(ACC.name||'?'))}</div><div><b style="color:#fff">${esc(ACC.name)}</b><div style="font-size:11px">${rl} · ${SYNC}</div></div></div><button class="btn g s" data-a="logout" style="margin-top:6px">Log out</button>`:''}
function setRole(){document.body.classList.toggle('ro',ROLE==='viewer');document.body.classList.toggle('mem',ROLE==='member');chip();render()}
const au=document.createElement('div');au.id='auth';au.dataset.mode='login';au.dataset.role='member';
au.innerHTML=`<form id="af"><div class="logo" style="color:var(--tx);padding:0 0 4px;font-size:22px">🧠 SmartGroup Team Analyzer<small>Team planning · task insights</small></div>
<div class="seg" id="sm"><button type="button" data-a="mode" data-id="login" class="on">Log in</button><button type="button" data-a="mode" data-id="signup">Create account</button></div>
<div class="seg" id="sr" aria-label="Choose your team role"><button type="button" data-a="arole" data-id="leader">👑 Team Leader</button><button type="button" data-a="arole" data-id="member" class="on">🙋 Team Member</button></div><div class="role-hint"><span><b>Team Leader</b> manages people, projects, tasks and analysis.</span><span><b>Team Member</b> views team work and updates their assigned tasks.</span></div>
<label class="su">Full name<input id="an" autocomplete="name"></label><label>Email<input id="ae" type="email" autocomplete="email" required></label>
<label class="su ms">Skills <span class="mu">(comma separated)</span><input id="amskills" placeholder="e.g. Java, React, communication"></label><label class="su ms">Skill level<select id="alevel"><option value="">Select skill level</option><option>Beginner</option><option>Intermediate</option><option>Advanced</option></select></label>
<label>Password<input id="ap" type="password" autocomplete="current-password" required></label><label class="su">Confirm password<input id="ap2" type="password" autocomplete="new-password"></label>
<label class="su ld">Leader access code<input id="ac" type="password" placeholder="Team leader code"><span class="mu" id="ach"></span></label>
<div id="aerr" role="alert"></div><button class="btn" id="ago" disabled style="display:block;width:100%;text-align:center">Log in</button><button type="button" class="text-link" data-a="forgot" id="forgot">Forgot password?</button><p class="mu" id="ast">Connecting…</p></form>`;
document.body.appendChild(au);
async function hint(){const h=$('#ach');h.textContent='';if(au.dataset.mode==='signup'&&au.dataset.role==='leader'){try{h.textContent=(await cfgGet())?'Ask an existing leader for the code.':'You are the first leader — this code will be required for other leaders.'}catch(e){}}}
function sync_(){const su=au.dataset.mode==='signup';$('#ago').textContent=su?'Create account':'Log in';$('#ap').autocomplete=su?'new-password':'current-password';$('#aerr').textContent='';[...$('#sm').children].forEach(b=>b.classList.toggle('on',b.dataset.id===au.dataset.mode));[...$('#sr').children].forEach(b=>b.classList.toggle('on',b.dataset.id===au.dataset.role));hint()}
A.mode=id=>{au.dataset.mode=id;sync_()};A.arole=id=>{au.dataset.role=id;sync_()};
A.logout=()=>{try{sessionStorage.removeItem('sgs')}catch(e){}ACC=null;mine=false;ROLE='leader';document.body.classList.remove('ro','mem');$('#chat').classList.remove('on');au.style.display='grid';chip()};
async function issueRecovery(id,a){const code=rnd().slice(0,16).toUpperCase(),salt=rnd();a.recoverySalt=salt;a.recoveryHash=await pw(code,salt);await accSet(id,a);return code}
function showRecovery(code,done){const d=document.createElement('div');d.className='modal';d.innerHTML=`<div class="recovery-card"><h3>Save your recovery key</h3><p class="mu">Keep this key somewhere safe. You will need it to reset your password. It is shown only once.</p><div class="recovery-key">${code}</div><button type="button" class="btn" style="width:100%;text-align:center" data-savekey>I saved my key</button></div>`;au.appendChild(d);d.querySelector('[data-savekey]').addEventListener('click',()=>{d.remove();done()})}
function showEmailVerification(email,done){const d=document.createElement('div');d.className='modal';d.innerHTML=`<form><h3 style="margin:0 0 6px">Verify your email</h3><p class="mu">We sent a six-digit code to <b>${esc(email)}</b>. Enter it to verify that this address belongs to you. The code expires in 15 minutes.</p><label>Email verification code<input name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required></label><div class="mu" role="alert" data-email-error style="min-height:18px"></div><div class="row" style="justify-content:flex-end"><button type="button" class="btn g" data-email-close>Cancel</button><button type="submit" class="btn">Verify email</button></div><button type="button" class="text-link" data-email-resend>Send a new code</button></form>`;document.body.appendChild(d);const formEl=d.querySelector('form'),error=d.querySelector('[data-email-error]');d.querySelector('[data-email-close]').addEventListener('click',()=>d.remove());d.querySelector('[data-email-resend]').addEventListener('click',async e=>{const b=e.currentTarget;b.disabled=true;try{await mailApi('/api/email/verification/request',{email});error.textContent='A new code was sent.'}catch(x){error.textContent=x.message}finally{b.disabled=false}});formEl.addEventListener('submit',async e=>{e.preventDefault();const b=formEl.querySelector('[type="submit"]');b.disabled=true;error.textContent='';try{const result=await mailApi('/api/email/verification/confirm',{email,code:new FormData(formEl).get('code')});d.remove();await done(result)}catch(x){error.textContent=x.message}finally{b.disabled=false}})}
