A.forgot=()=>{const d=document.createElement('div');d.className='modal';d.innerHTML=`<form id="reset-form"><h3 style="margin:0 0 6px">Reset your password</h3><p class="mu">Enter the email and recovery key saved when the account was created.</p><label>Account email<input name="email" type="email" autocomplete="email" required value="${esc($('#ae').value.trim())}"></label><label>Recovery key<input name="code" autocomplete="off" required></label><label>New password<input name="password" type="password" autocomplete="new-password" minlength="8" required></label><label>Confirm new password<input name="confirm" type="password" autocomplete="new-password" minlength="8" required></label><div id="reset-error" role="alert" class="mu" style="min-height:18px"></div><div class="row" style="justify-content:flex-end"><button type="button" class="btn g" data-close>Cancel</button><button type="submit" class="btn">Reset password</button></div></form>`;au.appendChild(d);d.querySelector('[data-close]').addEventListener('click',()=>d.remove());d.querySelector('form').addEventListener('submit',async e=>{e.preventDefault();const f=e.target,v=Object.fromEntries(new FormData(f)),err=d.querySelector('#reset-error'),button=f.querySelector('[type="submit"]');err.textContent='';if(v.password.length<8)return err.textContent='Password must be at least 8 characters.';if(v.password!==v.confirm)return err.textContent='Passwords do not match.';button.disabled=true;try{const id=await aid(v.email.trim().toLowerCase()),a=await accGet(id);if(!a)return err.textContent='No account found with this email.';if(!a.recoveryHash)return err.textContent='This account has no recovery key yet. Sign in with the current password once to create one.';if(await pw(v.code.replace(/\s/g,'').toUpperCase(),a.recoverySalt)!==a.recoveryHash)return err.textContent='That recovery key is not correct.';a.salt=rnd();a.hash=await pw(v.password,a.salt);await accSet(id,a);d.remove();toast('Password reset. Sign in with your new password.')}catch(x){err.textContent='Could not reset the password. Please try again.'}finally{button.disabled=false}})};
