const nm=$('#an').value.trim(),skills=csv($('#amskills').value),level=$('#alevel').value;if(!nm)return er('Enter your full name.');if(role==='member'&&!skills.length)return er('Add at least one skill.');if(role==='member'&&!level)return er('Choose your skill level.');if(p.length<8)return er('Password must be at least 8 characters.');if(p!==$('#ap2').value)return er('Passwords do not match.');if(acc)return er('An account with this email already exists. Log in instead.');
