/* ---------- deadline reminders & notifications ---------- */
const LEADS=()=>{try{return+localStorage.getItem('sgl')||3}catch(e){return 3}},rkey=()=>'sgn:'+(ACC?ACC.id:'local');
let RD=new Set();const NF=new Set();
const loadRD=()=>{try{RD=new Set(JSON.parse(localStorage.getItem(rkey())||'[]'))}catch(e){RD=new Set()}},saveRD=()=>{try{localStorage.setItem(rkey(),JSON.stringify([...RD]))}catch(e){}};
const dleft=d=>Math.round((new Date(d)-new Date(day(0)))/864e5);
function alerts(){const n=LEADS(),me=myM(),mm=ROLE==='member',out=[],own=t=>!mm||(me&&t.as==me.id);
S.t.filter(t=>open(t)&&t.dl&&own(t)).forEach(t=>{const d=dleft(t.dl);
if(d<0)out.push({k:`t${t.id}:o`,l:'e',t:'Task overdue',x:`"${t.title}" was due ${-d} day(s) ago`});
else if(d===0)out.push({k:`t${t.id}:0`,l:'w',t:'Due today',x:`"${t.title}"`});
else if(d<=n)out.push({k:`t${t.id}:${t.dl}`,l:'w',t:`Due in ${d} day(s)`,x:`"${t.title}"`})});
const pids=new Set(S.t.filter(own).map(t=>t.pj));
S.p.filter(p=>p.status!=='Completed'&&p.progress<100&&(!mm||pids.has(p.id))).forEach(p=>{const d=dleft(p.deadline);
if(d<0)out.push({k:`p${p.id}:o`,l:'e',t:'Project overdue',x:`${p.name} passed its deadline`});
else if(d<=n)out.push({k:`p${p.id}:${p.deadline}`,l:'w',t:`Project due in ${d} day(s)`,x:`${p.name} is at ${p.progress}%`})});
if(mm&&me)S.notices.filter(x=>x.memberId==me.id).forEach(x=>out.push({k:`a${x.id}`,l:'i',t:'New task assigned to you',x:`"${x.title}" · ${x.projectName}${x.priority?' · '+x.priority+' priority':''}${x.deadline?' · due '+x.deadline:''}`}));
if(!mm)S.t.filter(t=>open(t)&&!t.as).forEach(t=>out.push({k:`t${t.id}:u`,l:'i',t:'Unassigned task',x:`"${t.title}" needs an owner`}));
return out}
